1	// The write-surface gate for the growth PROMOTE stage (tasks/growth-promote/, this pack).
2	//
3	// Promote's write surface is bounded to the shared canon's two homes — packs/
4	// and skills/. This module is the GUARANTEE: any changed path outside packs/ or
5	// skills/ fails the gate. The promote AGENT never runs it and needn't know it
6	// exists — CI runs it automatically on the promote PR (checks-ci.yml, gated on
7	// the growth-promote branch prefix). The corpus principle it enforces: prose is
8	// a request; the post-hoc diff check is the guarantee.
9	//
10	// Why CI branch-gates it instead of registering it as a pack/skill check that
11	// runs on every PR: the "packs/skills only" boundary is true for PROMOTE alone —
12	// an ordinary engine change legitimately edits checks/, engine/, … Nothing in
13	// the tree marks a diff as a promote run, so no always-on check could self-gate
14	// to promote; the promote PR's branch prefix is the signal CI keys on.
15	import { buildContext } from '../../../../engine/checks/helpers/repo-context.mjs';
16	import { finding } from '../../../../engine/checks/helpers/findings.mjs';
17	
18	const inBounds = (p) => p.startsWith('packs/') || p.startsWith('skills/');
19	
20	const rule = {
21	  id: 'promote-scope',
22	  severity: 'blocking',
23	  description: 'The growth promote stage writes only under packs/ or skills/',
24	  doc: '.claudinite/local/packs/canon-curation/tasks/growth-promote/task.md',
25	  why: 'promote runs unattended with a fleet-wide token; a write outside the canon homes escapes the review-by-blast-radius boundary the growth lifecycle is built on',
26	
27	  // Every path the branch touches vs the merge-base — added/modified/untracked
28	  // (allFiles in changed mode) plus deletions — that is not under packs/ or
29	  // skills/ is one finding. No merge-base ⇒ no diff to scope ⇒ nothing to certify;
30	  // the CLI wrapper treats that as a hard refusal rather than a silent pass.
31	  run(ctx) {
32	    if (!ctx.mergeBase) return [];
33	    const touched = [...new Set([...ctx.allFiles, ...ctx.deleted])];
34	    return touched
35	      .filter((p) => !inBounds(p))
36	      .sort()
37	      .map((p) =>
38	        finding(rule, {
39	          file: p,
40	          what: `the promote phase touched ${p}, outside packs/ and skills/`,
41	          fix: 'a promoted lesson is portable canon — home it in a pack (prose or checks) or a skill; a lesson that can only live outside packs/ and skills/ is out of promote scope, so leave it local',
42	        })
43	      );
44	  },
45	};
46	
47	export default rule;
48	
49	// CLI — CI runs this on the promote PR: `node .claudinite/local/packs/canon-curation/promote-scope.mjs [root]`.
50	//   exit 0 — every changed path is under packs/ or skills/ (certified)
51	//   exit 1 — one or more stray paths (the boundary was breached; fail the PR)
52	//   exit 2 — no merge-base with the base branch, so the diff can't be scoped
53	if (process.argv[1] && (await import('node:fs')).realpathSync(process.argv[1]) === (await import('node:url')).fileURLToPath(import.meta.url)) {
54	  const root = process.argv[2] || process.cwd();
55	  const ctx = buildContext({ root, mode: 'changed' });
56	  if (!ctx.mergeBase) {
57	    console.error('promote-scope: no merge-base with the base branch — cannot scope the diff; refusing to certify.');
58	    process.exit(2);
59	  }
60	  const findings = rule.run(ctx);
61	  if (findings.length) {
62	    console.error(`promote-scope: FAIL — the promote phase may write only under packs/ or skills/, but this branch also touches ${findings.length} path(s):`);
63	    for (const f of findings) console.error(`  - ${f.file}`);
64	    console.error('\nHome each promoted lesson in a pack (prose or checks) or a skill; leave anything that can only live elsewhere local. Do not reach past packs/ and skills/.');
65	    process.exit(1);
66	  }
67	  console.log('promote-scope: OK — every changed path is under packs/ or skills/.');
68	}
